#!/usr/bin/env python3

import sys
import hashlib
import subprocess
import pickle

def encrypt_text(text):
    # WARNING: Weak hash (Bandit: B324)
    return hashlib.md5(text.encode()).hexdigest()

def run_shell(cmd):
    # Runs a shell command passed from user input (Bandit: B602)
    return subprocess.check_output(cmd, shell=True).decode()

def save_data(data, filename):
    # Pickle user data directly (Bandit: B301)
    with open(filename, "wb") as f:
        pickle.dump(data, f)

def load_data(filename):
    with open(filename, "rb") as f:
        return pickle.load(f)

def main():
    if len(sys.argv) < 2:
        print("Usage: {} <command> ...".format(sys.argv[0]))
        sys.exit(1)

    cmd = sys.argv[1]

    if cmd == "encrypt":
        if len(sys.argv) < 3:
            print("Usage: {} encrypt <text>".format(sys.argv[0]))
            sys.exit(1)
        text = sys.argv[2]
        print(encrypt_text(text))
    elif cmd == "shell":
        if len(sys.argv) < 3:
            print("Usage: {} shell <command>".format(sys.argv[0]))
            sys.exit(1)
        command = ' '.join(sys.argv[2:])
        print(run_shell(command))
    elif cmd == "save":
        if len(sys.argv) < 4:
            print("Usage: {} save <filename> <data>".format(sys.argv[0]))
            sys.exit(1)
        filename = sys.argv[2]
        data = sys.argv[3]
        save_data({'data': data}, filename)
        print("Saved.")
    elif cmd == "load":
        if len(sys.argv) < 3:
            print("Usage: {} load <filename>".format(sys.argv[0]))
            sys.exit(1)
        filename = sys.argv[2]
        data = load_data(filename)
        print("Loaded data:", data['data'])
    else:
        print("Unknown command.")

if __name__ == "__main__":
    main()

